/**
 * Hookline Rule Registry
 *
 * Single source of truth for every detection rule: a stable ID, the evidence
 * group it belongs to, its scam category, its weight, and a plain-language
 * description. Analyzers emit evidence tagged with a rule ID; the risk engine
 * looks the weight up here. This makes every rule citable (see
 * docs/RULES.md, generated by `npm run rules:doc`) and lets the eval harness
 * ablate rules one at a time.
 *
 * Scoring recap (see riskEngine.ts):
 *   points(item) = weight × severityFactor(item.severity)   (high 1, medium .5, low .25)
 *   score        = min(100, Σ over groups of max points in that group)
 *   verdict      = high_risk ≥ 50, suspicious ≥ 20, else safe
 *
 * IMPORTANT: changing a weight changes the reported metrics. Every change must
 * be re-evaluated and logged in eval/TUNING_LOG.md.
 */

import type { EvidenceType, EvidenceSeverity, ScamCategory } from "./types";

export type RuleScope = "url" | "email" | "page" | "text";

export interface RuleDef {
  id: string;
  group: EvidenceType;
  /** "general" = infrastructure signal that doesn't imply a specific scam type. */
  category: ScamCategory | "general";
  /** Points at "high" severity. */
  weight: number;
  defaultSeverity: EvidenceSeverity;
  scope: RuleScope[];
  /** If true, the rule is ignored for domains on the top-sites allow-list. */
  allowlistSuppressible: boolean;
  title: string;
  description: string;
  /** Where the signal comes from (guidance / literature), for the paper. */
  source?: string;
}

