export type RuleId = keyof typeof RULES;

export const ALL_RULE_IDS = Object.keys(RULES) as RuleId[];

export function getRule(id: RuleId): RuleDef {
  return RULES[id];
}

/** Short stable fingerprint of the rule set (ids + weights), recorded in eval output. */
export function rulesetFingerprint(): string {
  const s = ALL_RULE_IDS.map((id) => {
    const d = RULES[id];
    return `${id}:${d.weight}:${d.defaultSeverity}:${d.group}:${d.allowlistSuppressible ? 1 : 0}`;
  }).join("|");
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, "0");
}
